export function Context({
  scenario = "{{scenario}}",
  aware = {{aware}},
  userName = "{{userName}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 18, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", textAlign: "center" }}>
      <div style={{ width: 30, height: 30, borderRadius: 999, margin: "0 auto 10px", background: accent }} />
      <p style={{ margin: "0 0 6px", fontWeight: 600 }}>{aware ? `Good ${scenario}, ${userName}` : `Welcome, ${userName}`}</p>
      <p style={{ margin: 0, fontSize: 12, color: "#241430aa" }}>{aware ? "Uses context: time of day, current user" : "Same message regardless of context"}</p>
    </div>
  );
}
